"""
This script generates fixture data for the Planck distribution's probability mass function (PMF).

It writes the generated data to JSON files for large and small lambda values.
"""

import os
import json
import numpy as np
from scipy.stats import planck


def gen(x, lam, name):
    """
    Generate fixture data and write to file.

    Parameters
    ----------
    x : ndarray
        Input values.
    lam : ndarray
        Shape parameter.
    name : str
        Output filename.

    Examples
    --------
    >>> x = np.random.rand(1000) * 10
    >>> lam = np.random.rand(1000)
    >>> gen(x, lam, "data.json")
    """
    # Compute PDF values:
    z = np.array([planck.pmf(int(xi), pi) for xi, pi in zip(x, lam)])

    # Store data to be written to file as a dictionary:
    data = {
        "x": x.tolist(),
        "lambda": lam.tolist(),
        "expected": z.tolist()
    }

    # Based on the script directory, create an output filepath:
    filepath = os.path.join(dir_path, name)

    # Write the data to the output filepath as JSON:
    with open(filepath, "w", encoding='utf-8') as outfile:
        json.dump(data, outfile)

    # Include trailing newline
    with open(filepath, "a", encoding='utf-8') as outfile:
        outfile.write("\n")


# Get the directory in which this file resides:
dir_path = os.path.dirname(os.path.abspath(__file__))

# Large shape paramter:
x_ = np.round(np.random.rand(1000) * 10.0)
lam_ = (np.random.rand(1000) * 10) + 10
gen(x_, lam_, "large_lambda.json")

# Small shape parameter:
x_ = np.round(np.random.rand(1000) * 10.0)
lam_ = np.random.rand(1000) * 0.5
gen(x_, lam_, "small_lambda.json")
